def path_absent(
        path: _PATH,
) -> None:
    """Ensure the given ``path`` does **NOT** exist.

    *New in version 0.4.*

    If the given ``path`` does exist, it will be deleted. If the given ``path`` is a directory, this function will recursively delete all of the directory's contents before deleting the directory itself. The function processes the given ``path`` with :obj:`~flutils.normalize_path` to ensure compatibility across different systems and path representations.

    Args:
        path (:obj:`str`, :obj:`bytes` or :obj:`Path <pathlib.Path>`): The path to remove.

    Example:
        >>> from flutils.pathutils import path_absent
        >>> path_absent('~/tmp/test_path')
    """
    path = normalize_path(path)
    path = path.as_posix()
    path = cast(str, path)
    if os.path.exists(path):
        if os.path.islink(path):
            os.unlink(path)
        elif os.path.isdir(path):
            for root, dirs, files in os.walk(path, topdown=False):
                for name in files:
                    p = os.path.join(root, name)
                    if os.path.isfile(p) or os.path.islink(p):
                        os.unlink(p)
                for name in dirs:
                    p = os.path.join(root, name)
                    if os.path.islink(p):
                        os.unlink(p)
                    else:
                        os.rmdir(p)
            if os.path.isdir(path):
                os.rmdir(path)
        else:
            os.unlink(path)
